// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = typeof csvRaw === "string"
  ? csvRaw
  : JSON.stringify(csvRaw);

// Divide o CSV em linhas
const lines = text
  .split(/\r?\n/)
  .map(line => line.trim())
  .filter(Boolean);

// Cabeçalhos
const headers = lines[0]
  .split(",")
  .map(h => h.trim());

// Converte as linhas em objetos
const investimentos = lines.slice(1).map(line => {
  const cols = line
    .split(",")
    .map(c => c.trim());

  const obj = {};

  headers.forEach((h, i) => {
    obj[h] = cols[i] ?? "";
  });

  // Converte mínimo para número
  obj.minimo = Number(
    String(obj.minimo).replace(/[^\d]/g, "")
  ) || 0;

  return obj;
});

// Retorna os investimentos
return [
  {
    json: {
      investimentos
    }
  }
];

// Pega todos os dados recebidos
const entrada = $input.all();

// Pega os clientes enviados pelo Webhook
const clientes = $("Webhook").all().map(item => item.json);

// Pega os investimentos processados pelo primeiro Code
const investimentos = entrada[0]?.json?.investimentos || [];

// Escolhe uma mensagem aleatória
function pick(lista) {
  return lista[Math.floor(Math.random() * lista.length)];
}

// Processa cada cliente
const resultados = clientes.map(cliente => {

  const nome = cliente.nome;
  const email = cliente.email;
  const perfil = cliente.perfil?.toLowerCase() || "conservador";

  // Converte o saldo para número
  const saldoNum = Number(
    String(cliente.saldo || 0)
      .replace("R$", "")
      .replace(/\./g, "")
      .replace(",", ".")
      .trim()
  );

  // Procura investimentos compatíveis com o perfil
  const recomendacoes = investimentos.filter(
    investimento =>
      investimento.perfil?.toLowerCase() === perfil
  );

  // Escolhe uma recomendação
  const escolhido = recomendacoes.length > 0
    ? pick(recomendacoes)
    : investimentos[0];

  const motivo =
    `Recomendação baseada no seu perfil ${perfil} e no saldo disponível de ${cliente.saldo}.`;

  const mensagens = [
    `Olá ${nome}, encontramos uma recomendação de investimento para você: ${escolhido?.nome}.`,
    `${nome}, com base no seu perfil ${perfil}, encontramos uma opção que pode ser interessante: ${escolhido?.nome}.`,
    `Olá ${nome}! Sua recomendação personalizada está pronta: ${escolhido?.nome}.`
  ];

  return {
    nome,
    email,
    perfil,
    saldo_texto: cliente.saldo,
    saldo_num: saldoNum,
    recomendacao: escolhido,
    motivo,
    mensagem_escolhida: pick(mensagens)
  };
});

// Retorna os resultados
return [
  {
    json: {
      ok: true,
      total_clientes: resultados.length,
      total_investimentos: investimentos.length,
      resultados
    }
  }
];
